source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    fill_for = {0: 3, 3: 0}

    # Runs of at least two cells on a border send a ray inward.
    def edge_runs(values):
        i = 0
        while i < len(values):
            color = values[i]
            if color not in fill_for:
                i += 1
                continue
            j = i + 1
            while j < len(values) and values[j] == color:
                j += 1
            if j - i >= 2:
                yield i, j, color
            i = j

    # Left and right borders: each qualifying row is painted from its edge
    # up to the first non-background marker, or across if there is no marker.
    for edge in (0, w - 1):
        for start, end, color in edge_runs([grid[r][edge] for r in range(h)]):
            fill = fill_for[color]
            for r in range(start, end):
                direction = 1 if edge == 0 else -1
                c = edge + direction
                cells = []
                while 0 <= c < w:
                    cells.append(c)
                    if grid[r][c] != bg:
                        break
                    c += direction
                for c in cells:
                    out[r][c] = 4 if grid[r][c] != bg else fill

    # Top and bottom borders, same rule for vertical rays.
    for edge in (0, h - 1):
        for start, end, color in edge_runs(grid[edge]):
            fill = fill_for[color]
            for c in range(start, end):
                direction = 1 if edge == 0 else -1
                r = edge + direction
                cells = []
                while 0 <= r < h:
                    cells.append(r)
                    if grid[r][c] != bg:
                        break
                    r += direction
                for r in cells:
                    out[r][c] = 4 if grid[r][c] != bg else fill
    return out
'''
